CREATE TABLE cpf_webhook_delivery (delivery_no BIGINT GENERATED BY DEFAULT AS IDENTITY, delivery_id VARCHAR(64) NOT NULL, idempotency_key VARCHAR(255) NOT NULL, transaction_id VARCHAR(64) NOT NULL, target_uri VARCHAR(1000) NOT NULL, delivery_status VARCHAR(32) NOT NULL, attempt_count INTEGER DEFAULT 0 NOT NULL, http_status INTEGER, result_detail VARCHAR(2000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT pk_cpf_webhook PRIMARY KEY(delivery_no), CONSTRAINT uk_cpf_webhook_delivery UNIQUE(delivery_id), CONSTRAINT uk_cpf_webhook_idem UNIQUE(idempotency_key));
CREATE INDEX ix_cpf_webhook_status ON cpf_webhook_delivery(delivery_status,updated_at);
